// Real product photos (supplied by the factory we distribute for) shown as a model gallery on category pages.
// Generated by scripts/gallery/build.py from the raw photos → public/img/g/*.webp + lib/gallery.json.
import gallery from "./gallery.json";

export type GalleryItem = { src: string; w: number; h: number; ar: string; en: string; code?: string };
export type Gallery = { title_ar: string; title_en: string; note_ar: string; note_en: string; items: GalleryItem[] };

const G = gallery as Record<string, Gallery>;

export const galleryFor = (slug: string): Gallery | undefined => (G[slug]?.items.length ? G[slug] : undefined);
